"""Shared paths for files generated by PiperSynth example scripts."""

from __future__ import annotations

import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
ARTEFACT_DIR = PROJECT_ROOT / "example-artefacts"
_OUTPUT_ENV = "PIPERSYNTH_EXAMPLE_OUTPUT_DIR"

if sys.path and Path(sys.path[0]).resolve() == Path(__file__).resolve().parent:
    sys.path.pop(0)


def artefact_dir() -> Path:
    """Return and create the directory used for generated example artefacts."""
    path = Path(os.environ.get(_OUTPUT_ENV, ARTEFACT_DIR)).resolve()
    path.mkdir(parents=True, exist_ok=True)
    return path


def artefact_path(name: str | Path) -> Path:
    """Resolve one output path without permitting traversal outside the root."""
    root = artefact_dir()
    path = (root / name).resolve()
    if path != root and root not in path.parents:
        raise ValueError(f"artefact path escapes {root}: {name}")
    path.parent.mkdir(parents=True, exist_ok=True)
    return path
